INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT156-S4-Q20$batch05$, 156, 4, 20, $batch05$Necessary Assumption$batch05$, $batch05$Azalea bushes flourish in acidic soil. Clay soil, while rarely acidic, can be mixed with other types of soil to create a soil that is acidic. Hence, azalea bushes can be made to flourish in clay soil.$batch05$, $batch05$Which one of the following is an assumption on which the argument depends?$batch05$, $batch05$B$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q20$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$Mixing an acidic soil with another type of soil always results in an acidic soil.$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$Clay soil that is mixed with certain other types of soil is still clay soil.$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$Whenever clay soil is mixed with other types of soil, an acidic soil results.$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$Some plants do not flourish in acidic soil.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$Azalea bushes do as well in treated clay soils as in naturally acidic soils.$batch05$, $batch05$Too Strong$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Azalea bushes can be made to flourish in clay soil.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Azaleas flourish in acidic soil. Clay soil, mixed with other soils, can become acidic.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Here is the sleight of hand. Once you mix clay with other soils, is it still *clay soil*? If the mixture counts as something else, the azaleas are flourishing in a new soil, not in clay. The conclusion depends on the mixture keeping its name.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: clay soil mixed with other soils still counts as clay soil.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$"Always" is far more than needed. The stimulus only says clay *can* be mixed into something acidic.$batch05$), ($batch05$B$batch05$, $batch05$Negate it: "clay soil mixed with other soils is *no longer* clay soil." Then the azaleas grow in a different soil, and the claim about clay soil falls apart.$batch05$), ($batch05$C$batch05$, $batch05$The argument needs only some mixtures to turn acidic, not every one.$batch05$), ($batch05$D$batch05$, $batch05$Other plants are beside the point.$batch05$), ($batch05$E$batch05$, $batch05$Azaleas only need to flourish. They do not need to do *as well* as they do in naturally acidic soil.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT156-S4-Q20$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
